+fn r_small_threshold_for(pair: KalPair, pass: KalPass) -> usize {
+    let default = match (pair, pass) {
+        (KalPair::Pair1, KalPass::Backward) => R_SMALL_THRESHOLD_PAIR1_BK,
+        _ => R_SMALL_THRESHOLD,
+    };
+    let mut threshold = env_usize("KAL_R_SMALL_THRESHOLD").unwrap_or(default);
+
+    let global_pass = match pass {
+        KalPass::Forward => "KAL_R_SMALL_THRESHOLD_FWD",
+        KalPass::Backward => "KAL_R_SMALL_THRESHOLD_BK",
+    };
+    if let Some(v) = env_usize(global_pass) {
+        threshold = v;
+    }
+
+    let (pair_all, pair_pass) = match (pair, pass) {
+        (KalPair::Pair1, KalPass::Forward) => (
+            Some("KAL_PAIR1_R_SMALL_THRESHOLD"),
+            Some("KAL_PAIR1_R_SMALL_THRESHOLD_FWD"),
+        ),
+        (KalPair::Pair1, KalPass::Backward) => (
+            Some("KAL_PAIR1_R_SMALL_THRESHOLD"),
+            Some("KAL_PAIR1_R_SMALL_THRESHOLD_BK"),
+        ),
+        (KalPair::Pair2, KalPass::Forward) => (
+            Some("KAL_PAIR2_R_SMALL_THRESHOLD"),
+            Some("KAL_PAIR2_R_SMALL_THRESHOLD_FWD"),
+        ),
+        (KalPair::Pair2, KalPass::Backward) => (
+            Some("KAL_PAIR2_R_SMALL_THRESHOLD"),
+            Some("KAL_PAIR2_R_SMALL_THRESHOLD_BK"),
+        ),
+        (KalPair::Default, _) => (None, None),
+    };
+    if let Some(name) = pair_all {
+        if let Some(v) = env_usize(name) {
+            threshold = v;
+        }
+    }
+    if let Some(name) = pair_pass {
+        if let Some(v) = env_usize(name) {
+            threshold = v;
+        }
+    }
+
+    threshold
+}

+pub fn build_builder() -> crate::point_add::B {
+    configure_sub1000_trailmix_route();
+
+    let mut circ = circuit::Circuit::new();
+    circ.set_section("trailmix_shrunken_pz");
+    let mut tx = circ.alloc_qreg_bits("tx", 256);
+    let mut ty = circ.alloc_qreg_bits("ty", 256);
+    let ox: Vec<circuit::Cbit> = (0..256).map(|_| circ.alloc_input_bit()).collect();
+    let oy: Vec<circuit::Cbit> = (0..256).map(|_| circ.alloc_input_bit()).collect();
+
+    ec::point_add::ec_add_inplace_shrunken_pz(&mut circ, &mut tx, &mut ty, &ox, &oy);

+    fn new_count_only() -> Self {
+        let mut b = Self::new();
+        b.count_only = true;
+        b.fiat_hash = Self::fiat_hash_from_env();
+        b
+    }
+    fn fiat_hash_from_env() -> Option<Shake256> {
+        let ops_len = std::env::var("POINT_ADD_HASH_OPS_LEN")
+            .ok()
+            .and_then(|s| s.parse::<u64>().ok())?;
+        let mut hasher = Shake256::default();
+        hasher.update(b"quantum_ecc-fiat-shamir-v2");
+        hasher.update(&ops_len.to_le_bytes());
+        Some(hasher)
+    }
+    pub(crate) fn update_fiat_hash_op(hasher: &mut Shake256, op: &Op) {
+        hasher.update(&[op.kind as u8]);
+        hasher.update(&op.q_control2.0.to_le_bytes());
+        hasher.update(&op.q_control1.0.to_le_bytes());
+        hasher.update(&op.q_target.0.to_le_bytes());
+        hasher.update(&op.c_target.0.to_le_bytes());
+        hasher.update(&op.c_condition.0.to_le_bytes());
+        hasher.update(&op.r_target.0.to_le_bytes());
+    }
+    pub(crate) fn clone_fiat_hash(&self) -> Option<Shake256> {
+        self.fiat_hash.clone()
+    }
+    fn push_op(&mut self, op: Op) {
+        self.counted_ops += 1;
+        self.counted_kind_ops[op.kind as usize] += 1;
+        self.counted_phase_kind_ops[op.kind as usize] += 1;
+        if let Some(hasher) = &mut self.fiat_hash {
+            Self::update_fiat_hash_op(hasher, &op);
+        }
+        if !self.count_only {
+            self.ops.push(op);

